const { useState } = React;

function ProductList() {
  const [products, setProducts] = useState([
    { id: 1, name: '셔츠' },
    { id: 2, name: '모자' },
  ]);

  function addShoes() {
    setProducts((previous) => [...previous, { id: 3, name: '신발' }]);
  }

  function removeProduct(targetId) {
    setProducts((previous) => previous.filter((product) => product.id !== targetId));
  }

  return (
    <section>
      <button type="button" onClick={addShoes}>신발 추가</button>
      <ul>{products.map((product) => (
        <li key={product.id}>{product.name} <button type="button" onClick={() => removeProduct(product.id)}>삭제</button></li>
      ))}</ul>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<ProductList />);

